// Turns the downloaded emoji.gg packs in docs/*-emojigg-pack/ into
//   public/emoji/<pack>/<code>.<ext>
//   lib/emoji/packs.generated.ts
//
// Same shape as scripts/build-voxel-emotes.mjs: the pack folders are the
// source, the generated file is committed, and this only needs re-running when
// a pack is added or replaced.
//
// Run: node scripts/build-emoji-packs.mjs

import { readdirSync, mkdirSync, copyFileSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { join, extname, basename } from "node:path";

const DOCS = "docs";
const OUT_ASSETS = join("public", "emoji");
const OUT_TS = join("lib", "emoji", "packs.generated.ts");

/** `896989-pepe-emojigg-pack` -> `pepe` */
const packSlug = (dir) => dir.replace(/^\d+-/, "").replace(/-emojigg-pack$/, "");

/** `121023-pepetyping.gif` -> `pepetyping`; `1096_FoxxoHmph.png` -> `foxxohmph` */
const codeOf = (file) =>
    basename(file, extname(file))
        .replace(/^\d+[-_]/, "")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "");

/** Title-cases a slug for the picker's category label. */
const titleOf = (slug) =>
    slug.split("-").map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");

const packDirs = readdirSync(DOCS).filter((d) => d.endsWith("-emojigg-pack")).sort();
if (!packDirs.length) {
    console.error("no *-emojigg-pack directories in docs/");
    process.exit(1);
}

if (existsSync(OUT_ASSETS)) rmSync(OUT_ASSETS, { recursive: true });
mkdirSync(OUT_ASSETS, { recursive: true });

const seen = new Map(); // code -> pack, for collision reporting
const packs = [];

for (const dir of packDirs) {
    const slug = packSlug(dir);
    const destDir = join(OUT_ASSETS, slug);
    mkdirSync(destDir, { recursive: true });

    const emojis = [];
    for (const file of readdirSync(join(DOCS, dir)).sort()) {
        const ext = extname(file).toLowerCase();
        if (![".png", ".gif", ".webp", ".jpg", ".jpeg"].includes(ext)) continue;

        let code = codeOf(file);
        if (!code) continue;
        // Codes are one namespace (chat types `:code:`), so a duplicate has to
        // be disambiguated rather than silently overwrite the earlier pack.
        if (seen.has(code)) code = `${code}${slug.replace(/[^a-z0-9]/g, "").slice(0, 4)}`;
        if (seen.has(code)) continue;
        seen.set(code, slug);

        copyFileSync(join(DOCS, dir, file), join(destDir, `${code}${ext}`));
        emojis.push({ code, src: `/emoji/${slug}/${code}${ext}` });
    }

    if (emojis.length) packs.push({ slug, title: titleOf(slug), emojis });
    console.log(`${slug.padEnd(28)} ${emojis.length} emoji`);
}

const total = packs.reduce((n, p) => n + p.emojis.length, 0);

const body = `// GENERATED by scripts/build-emoji-packs.mjs — do not edit by hand.
// Source: docs/*-emojigg-pack/. Re-run the script after adding a pack.
//
// ${packs.length} packs, ${total} emoji.

export type PackEmoji = { code: string; src: string };
export type EmojiPack = { slug: string; title: string; emojis: PackEmoji[] };

export const EMOJI_PACKS: EmojiPack[] = ${JSON.stringify(packs, null, 4)};

/** Flat lookup by code, across every pack. */
export const PACK_EMOJI_BY_CODE: Map<string, PackEmoji> = new Map(
    EMOJI_PACKS.flatMap((p) => p.emojis.map((e) => [e.code, e] as const)),
);
`;

mkdirSync(join("lib", "emoji"), { recursive: true });
writeFileSync(OUT_TS, body);
console.log(`\n${packs.length} packs, ${total} emoji -> ${OUT_TS}`);
